{"function": "() => {
  // Get all text nodes from the main article content
  const article = document.querySelector('article');
  if (!article) return 'No article element found';

  // Function to get all text nodes recursively
  const getTextNodes = (node) => {
    const nodes = [];
    if (node.nodeType === Node.TEXT_NODE) {
      nodes.push(node);
    } else {
      for (let child of node.childNodes) {
        nodes.push(...getTextNodes(child));
      }
    }
    return nodes;
  };

  const textNodes = getTextNodes(article);
  let fullText = '';
  for (let node of textNodes) {
    fullText += node.textContent + ' ';
  }

  // Split into sentences (simple regex)
  const sentences = fullText.match(/[^.!?]+[.!?]+/g) || [];

  // Filter sentences containing "compound" (case-insensitive)
  const compoundSentences = sentences.filter(s => /\bcompound\b/i.test(s));

  // Return results
  return {
    totalSentences: sentences.length,
    compoundSentenceCount: compoundSentences.length,
    compoundSentences: compoundSentences.map(s => s.trim())
  };
}"}

